import type { AxisKey, ReferenceEntry } from './references';

const axes: AxisKey[] = ['est', 'rep', 'pod', 'imi', 'dip', 'int', 'eco', 'con', 'com', 'rel', 'mor', 'tec'];
type Point = readonly [AxisKey, number, string];
type Seed = readonly [
  id: string, name: string, period: string, rationale: string, caveat: string,
  sourceTitle: string, url: string, sourceNote: string, points: readonly Point[],
];

const seed = (...row: Seed): ReferenceEntry => {
  const [id, name, period, rationale, caveat, sourceTitle, url, sourceNote, points] = row;
  const values = Object.fromEntries(points.map(([axis, value]) => [axis, value])) as Partial<Record<AxisKey, number>>;
  const supported = points.map(([axis]) => axis);
  const unknown = axes.filter((axis) => !supported.includes(axis));
  if (new Set(supported).size !== supported.length || points.some(([, value]) => value === 50 || value < 0 || value > 100)) {
    throw new Error(`Invalid religious ideology evidence vector: ${id}`);
  }
  return {
    id: `ideology-${id}`, kind: 'ideology', category: 'ideology', name, period,
    vec: Object.fromEntries(axes.map((axis) => [axis, values[axis] ?? 50])) as Record<AxisKey, number>,
    rationale,
    caveats: `${caveat} Eixos sem apoio documental específico (${unknown.join(', ')}) ficam em 50 como desconhecidos, não como posições moderadas.`,
    sources: [{ title: sourceTitle, url, note: sourceNote }],
    evidence: Object.fromEntries(supported.map((axis) => [axis, 'medium'])) as ReferenceEntry['evidence'],
    axisEvidence: Object.fromEntries(points.map(([axis, , why]) => [axis, { sourceTitles: [sourceTitle], rationale: why }])),
  };
};

